#!/usr/bin/env bash
# Build reference mruby as a pure-capability domain, running precompiled bytecode.
#
# Needs an mruby tree that has ALREADY been built for the host, because two of
# its inputs are generated by mruby's own build system and are target
# independent: build/host/mrblib/mrblib.c (the Ruby-level standard library, as
# bytecode) and build/host/include/mruby/presym/ (the symbol tables). Produce
# them with `rake` in the mruby tree; this script does not reimplement that.
set -euo pipefail

SCRIPT_DIR=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)
source "$SCRIPT_DIR/../../tests/capstone-test-env.sh"

REPO_ROOT=$CAPSTONE_REPO_ROOT
CLANG=${CAPSTONE_CLANG:?}
LD_LLD=${CAPSTONE_LD_LLD:?}
OUT_DIR=${OUT_DIR:-$CAPSTONE_TMP_ROOT/musl-capstone-mruby}
OBJ_DIR="$OUT_DIR/obj"
OUT_DOM=${OUT_DOM:-$OUT_DIR/mruby_probe.dom}
OUT_HOST=${OUT_HOST:-$OUT_DIR/mruby_probe.user}

RUNTIME_DIR="$SCRIPT_DIR/../runtime"
LINKER_SCRIPT="$REPO_ROOT/capstone/my_first_domain/link.ld"
GUEST_CC=${GUEST_CC:-$CAPSTONE_BUILDROOT_DIR/build/host/bin/riscv64-buildroot-linux-gnu-gcc}
LIBCAPSTONE_C="$REPO_ROOT/capstone/caplifive-buildroot/package/modcapstone/userspace/lib/libcapstone.c"
SETJMP_SRC="$REPO_ROOT/xlang/lua-cdp/capstone-lua/capstone_setjmp.S"

# MRUBY_GPCT=1 builds the whole domain under the gp-captable ABI: globals are
# reached through a cap table the entry glue builds from a descriptor, instead of
# through `gp` as a data capability. The reason is silicon, not tidiness -- under
# the default ABI QEMU FABRICATES gp from a linear PCC on every use (>=6000 times
# per mruby run, measured), the RTL never does that, and so mruby as built by the
# default path cannot run on the board at all.
#
# Everything the switch needs already exists: __capstone_yield in the gp-captable
# glue (behind CAPSTONE_GLUE_YIELD), the init/fini markers in link-gpfree.ld, and
# malloc.c's runtime choice of heap. See plans/20-08-2026_mruby-gp-captable.md.
GPCT=${MRUBY_GPCT:-0}
# LTO IS ORTHOGONAL TO THE ABI, and separating them is the point: the pair
# "default ABI with LTO" is what discriminates an LTO codegen fault from a
# gp-captable one, and it cannot be expressed while the two are one switch.
# MRUBY_GPCT=lto stays as the shorthand it always was.
LTO=${MRUBY_LTO:-0}
[[ "$GPCT" == "lto" ]] && LTO=1
LADDER="$REPO_ROOT/capstone/tests/runtime-qemu/silicon-ladder"
GPFREE="$REPO_ROOT/capstone/tests/runtime-qemu/gp-free-domain"
# MRUBY_GPCT=lto is gp-captable PLUS full LTO, and it is the only variant that can
# actually be correct for a multi-object domain: the descriptor is emitted per MODULE,
# so separate objects each get their own and the glue reads only the first. LTO
# presents one module. See gp-free-domain/multi-tu-slot-collision.sh, which shows both
# halves in one run. MRUBY_GPCT=1 keeps the non-LTO variant for comparison.
if [[ "$GPCT" != "0" && "$LTO" == "1" ]]; then
  ARCHIVE=${ARCHIVE:-$CAPSTONE_TMP_ROOT/musl-capstone-build-lto/libc-capstone.a}
elif [[ "$GPCT" == "0" && "$LTO" == "1" ]]; then
  ARCHIVE=${ARCHIVE:-$CAPSTONE_TMP_ROOT/musl-capstone-build-lto-defabi/libc-capstone.a}
elif [[ "$GPCT" != "0" ]]; then
  # A DIFFERENT ARCHIVE, not the same one relinked. Every member has to be compiled
  # with the flag, so pointing at the default archive would link gp-ABI objects into
  # a gp-captable image and fail in a way that looks like a codegen bug.
  ARCHIVE=${ARCHIVE:-$CAPSTONE_TMP_ROOT/musl-capstone-build-gpct/libc-capstone.a}
else
ARCHIVE=${ARCHIVE:-$CAPSTONE_TMP_ROOT/musl-capstone-build/libc-capstone.a}
fi
MUSL_SRC_DIR=${MUSL_SRC_DIR:-$CAPSTONE_TMP_ROOT/musl-src/musl-1.2.5}
MRUBY_SRC=${MRUBY_SRC:-$HOME/cheri/mruby-purecap}

NEEDED=("$ARCHIVE" "$MUSL_SRC_DIR/arch/capstone64/syscall_arch.h" "$SETJMP_SRC"
        "$MRUBY_SRC/src/vm.c" "$MRUBY_SRC/build/host/mrblib/mrblib.c"
        "$MRUBY_SRC/build/host/bin/mrbc")

# The generated symbol tables are required ONLY BY TREES THAT HAVE PRESYM, which
# mruby gained in 3.0. The corpus pins nine versions spanning 2017-2026 and most
# of them predate it, so demanding the table unconditionally rejected a perfectly
# buildable tree with "missing prerequisite" -- a prerequisite it has no concept
# of. Keyed on the tree's own header rather than on a version number, because the
# version is not what the compile actually depends on. A tree that DOES need the
# table and lacks it still fails, loudly, on the missing include.
[[ -f "$MRUBY_SRC/include/mruby/presym.h" ]] && \
  NEEDED+=("$MRUBY_SRC/build/host/include/mruby/presym/id.h")

for needed in "${NEEDED[@]}"; do
  [[ -e "$needed" ]] || { echo "missing prerequisite: $needed" >&2; exit 2; }
done

# THE FOUR CONFIG MACROS, all upstream-supported, each forced by this machine:
#
#   MRB_NO_BOXING           boxing_word.h packs an mrb_value into one 64-bit
#                           word by tagging the pointer; its static assert fails
#                           outright with 16-byte pointers. This one is ours --
#                           the CHERI port did not need it.
#   MRB_NO_DIRECT_THREADING the VM's computed-goto dispatch is a second,
#                           independent absolute-addressed jump table, the same
#                           mechanism Lua needed LUA_USE_JUMPTABLE=0 for.
#   POOL_ALIGNMENT=16       the parser pool hands out 8-aligned cells whose
#                           node* fields are 16-byte capabilities.
#   MRB_USE_METHOD_T_STRUCT the method table otherwise stores a tagged pointer.
#
# The last two come from the CHERI port (xlang/cheri/mruby-port/README.md) and
# are about pointer WIDTH, which is why they carry over; its TLS flags do not,
# because a domain has no dynamic linker.
#
# MRB_NO_STDIO: not because stdio is missing -- printf works now -- but because
# this first probe is the VM alone. Adding mruby-print is the next step.
MRUBY_FLAGS=(
  -target capstone64-unknown-elf
  -Xclang -target-feature -Xclang +m
  -Xclang -target-feature -Xclang +a
  -nostdinc -ffreestanding -fno-builtin
  -fno-optimize-sibling-calls -fno-jump-tables
  -D_XOPEN_SOURCE=700
  -DMRB_NO_BOXING -DMRB_NO_DIRECT_THREADING -DMRB_NO_STDIO
  -DPOOL_ALIGNMENT=16 -DMRB_USE_METHOD_T_STRUCT
  # BOTH SPELLINGS of the same switch. mruby renamed it: trees before 3.x call it
  # MRB_METHOD_T_STRUCT, and there the DEFAULT stores the method as a tagged
  # POINTER -- `(mrb_method_t)((((uintptr_t)(fn))<<2)|MRB_METHOD_FUNC_FL)`, an
  # integer cast back to a pointer type, i.e. a forged capability. It faults in
  # mrb_define_method_raw sixteen allocations into mrb_open. Passing only the
  # newer name looked like "this tree has no such option" and cost a boot; the
  # struct variant was in the tree all along, behind the other name. Defining a
  # macro a tree does not have is harmless, so both go unconditionally.
  -DMRB_METHOD_T_STRUCT
  # mrb_alignas RAISED TO AT LEAST 16, not overridden to it.
  #
  # mruby 3.4 annotates its static RProc objects `mrb_alignas(8)` so the low
  # three bits of the pointer stay free. A struct holding capabilities already
  # needs 16, and asking for LESS than the natural alignment is an error:
  #   "requested alignment is less than minimum alignment of 16 for type
  #    'const struct RProc'"
  # The intent is a floor, so a floor is what this expresses; a tree that ever
  # asks for 32 keeps its 32. common.h defines the macro under `#ifndef`, so a
  # command-line definition simply wins and no header shadow is needed. Only the
  # two newest pinned trees use it, always with 8 (checked, not assumed).
  "-Dmrb_alignas(n)=__attribute__((aligned(((n)<16)?16:(n))))"
  # MRUBY_PROBE_STACK_DOUBLING=1 adds -DMRB_STACK_EXTEND_DOUBLING, an upstream
  # mruby option. It is DIAGNOSTIC and must not be on for a published number:
  # mruby's default is LINEAR stack growth, chosen because it "saves memory on
  # small devices" -- true of the live set, and exactly wrong for an allocator
  # that never reclaims, where the cumulative carve is the sum of every stack
  # size ever allocated and linear growth makes that sum quadratic. Turning it
  # on separates "the arena is too small for this workload" from "the workload
  # stops for some other reason".
  ${MRUBY_PROBE_STACK_DOUBLING:+-DMRB_STACK_EXTEND_DOUBLING}
  # PROBE_EXTRA_DEFINES carries the defines a row's OWN build_config.rb sets --
  # the corpus's reference configuration, not ours. Space-separated names, no -D.
  ${PROBE_EXTRA_DEFINES:+$(for d in $PROBE_EXTRA_DEFINES; do printf -- "-D%s " "$d"; done)}
  # musl's <math.h> classify macros end in a long-double arm that -O0 does not
  # fold away, so numeric.c and fmt_fp.c pull __signbitl, __fpclassifyl and
  # __extenddftf2, none of which exist (C-20). A -D on this command line does
  # NOT work -- math.h redefines the same names later. The header explains why
  # a forced include does.
  -include "$SCRIPT_DIR/../libc-ext/capstone-math-double.h"
  # FIRST, so the shadowed copy of string.h below wins over the tree's.
  -I"$OBJ_DIR/hdr"
  -I"$MRUBY_SRC/include" -I"$MRUBY_SRC/build/host/include"
  -I"$MUSL_SRC_DIR/arch/capstone64" -I"$MUSL_SRC_DIR/arch/generic"
  -I"$MUSL_SRC_DIR/obj/include" -I"$MUSL_SRC_DIR/include"
  -ffunction-sections -fdata-sections
  -O0 -w -Wno-int-conversion -Wno-error=int-conversion
)

# MRUBY_PROBE_MRBTEST_GEMS=1 widens the suite from core-only to EVERY gem, which
# needs three changes to the flags above and nothing else.
#
# -DMRB_NO_STDIO COMES OUT. It was right when this libc had no stdio; it does
# now, and three gems refuse to compile with it by design -- mruby-print and
# mruby-io both `#error "... conflicts 'MRB_NO_STDIO'"`, and mruby-socket needs
# mruby-io's header. Measured before removing it: mruby's own src/*.c compiles
# 31/31 either way, so dropping it costs the core nothing.
#
# -D_BSD_SOURCE, because musl puts NI_MAXHOST behind it (netdb.h:132) and
# socket.c uses it. _XOPEN_SOURCE=700 alone does not expose it.
#
# mruby-io's include/ on the path, because socket.c includes mruby/ext/io.h and
# only that gem ships it.
#
# Applied ONLY in this mode, so the core-only suite that has already been
# measured keeps building byte-identically.
if [[ ${MRUBY_PROBE_MRBTEST_GEMS:-0} == 1 ]]; then
  _wide=()
  for f in "${MRUBY_FLAGS[@]}"; do
    [[ $f == -DMRB_NO_STDIO ]] && continue
    _wide+=("$f")
  done
  MRUBY_FLAGS=("${_wide[@]}" -D_BSD_SOURCE -I"$MRUBY_SRC/mrbgems/mruby-io/include")
  # mruby-eval is one of the 32 and it CALLS THE PARSER (mrb_parse_nstring,
  # mrb_generate_code, mrbc_context_new). Without the compiler gem the link ends
  # with six undefined symbols, so this mode implies it rather than leaving the
  # caller to discover that. The parser also brings -DMRUBY_PROBE_PARSER, whose
  # S6/S7 stages sit after the mrbtest hook in capstone_main and are therefore
  # never reached here.
  MRUBY_WITH_PARSER=1
fi

# APPENDED HERE, not inside the array literal, because the mrbtest-gems mode above
# REBUILDS MRUBY_FLAGS from a filtered copy -- a flag added at the literal would be
# carried through by that loop only by luck, and dropped the day the filter grows a
# second exclusion. After the last assignment there is exactly one place to look.
# DEFINED HERE, above every reader. They depend on nothing, and the mrbtest block
# further down dereferences them under `set -u` -- which made that path fail with
# "MRUBY_DOMAIN_HEAP: unbound variable" unless the caller happened to pass one.
MRUBY_DOMAIN_STACK=${MRUBY_DOMAIN_STACK:-$((256 * 1024))}
MRUBY_DOMAIN_HEAP=${MRUBY_DOMAIN_HEAP:-$((1024 * 1024 - 1536 - 256 * 1024))}
MRUBY_DOMAIN_DATA=$(( MRUBY_DOMAIN_HEAP + MRUBY_DOMAIN_STACK ))

if [[ "$GPCT" != "0" ]]; then
  MRUBY_FLAGS+=(-mllvm -capstone-gp-captable)
fi
# EVERY C OBJECT MUST BE BITCODE IN THIS MODE, with no exceptions. One native object
# that defines a global would emit its own descriptor fragment and put the collision
# straight back; stack_reserve.c is the easy one to forget, and it picks this up only
# because it is compiled with MRUBY_FLAGS like everything else.
LTO_LINK_FLAGS=()
if [[ "$LTO" == "1" ]]; then
  MRUBY_FLAGS+=(-flto)
  # Codegen happens in the LINKER under LTO, so any -mllvm option has to be re-enabled
  # there; a compile-time one does not reach it. Only the ABI switch is such an option.
  # Flags like -fno-jump-tables and -fno-optimize-sibling-calls need no repeat: clang
  # records them as function attributes in the IR, which survives into the LTO backend.
  [[ "$GPCT" != "0" ]] && LTO_LINK_FLAGS=(--plugin-opt=-capstone-gp-captable)
fi

rm -rf "$OBJ_DIR"; mkdir -p "$OBJ_DIR"

# The EMBEDDED-STRING length field, widened in a SHADOW of the headers.
#
# mruby keeps a short string inside the object header with its length in a
# bitfield of `flags`. The capacity derives from sizeof(void*) and so grows with
# the pointer while the field does not; at 16-byte capabilities it no longer
# fits and src/string.c stops the build with "pointer size too big for embedded
# string". patch-embed-len.py has the derivation, both layout schemes, and the
# reason for widening rather than capping the capacity.
#
# It is the SECOND source change the port needs, alongside the parse.y line, and
# it is easy to miss because `mruby-purecap` already carries it: that tree
# differs from its pinned upstream commit by this one line and nothing else, so
# building against it hides the requirement entirely. Row 4 found it.
#
# Shadowed, not patched into the corpus tree, because `xlang/repro/<n>/mruby` is
# the corpus's pinned artefact and must stay byte-identical -- same reason
# patch-parser.py writes into the build directory. -D cannot do this job: the
# header defines the macro unconditionally and would simply override it.
#
# The WHOLE header directory is copied, not just string.h: mruby's headers
# include each other by bare name (`#include "common.h"`), which resolves
# relative to the INCLUDING file, so a lone shadowed header sits in a directory
# with no siblings and fails to find them.
mkdir -p "$OBJ_DIR/hdr"
STRING_C_GEN=""
if [[ -f "$MRUBY_SRC/include/mruby/string.h" ]]; then
  cp -r "$MRUBY_SRC/include/mruby" "$OBJ_DIR/hdr/mruby"
  embed_out=$(python3 "$SCRIPT_DIR/patch-embed-len.py" \
                      "$MRUBY_SRC" "$OBJ_DIR/hdr/mruby/string.h" "$OBJ_DIR/gen") || exit 2
  # Older trees also write the width out as a literal in a static assert, so
  # they need src/string.c shadowed as well; the script says so on stdout.
  [[ $embed_out == SHADOW_SRC=* ]] && STRING_C_GEN=${embed_out#SHADOW_SRC=}
fi

OBJS=()

# The Ruby chunk, compiled to bytecode BY THE HOST mrbc and emitted as a C
# array. This is the step that keeps the parser out of the domain.
"$MRUBY_SRC/build/host/bin/mrbc" -B probe_irep -o "$OBJ_DIR/probe_irep.c" \
                                 "$SCRIPT_DIR/probe.rb"

# STAGE 7 needs a LADDER of ireps rather than one: the fault is inside
# mrb_top_run, and an interpreter loop does not decompose by call structure. It
# decomposes by BYTECODE, so each rung is a slightly larger Ruby chunk and the
# last rung that returns names the construct. All six go into ONE image.
if [[ ${MRUBY_PROBE_STAGE:-0} -ge 7 ]]; then
  : > "$OBJ_DIR/ladder_ireps.c"
  for rb in "$SCRIPT_DIR"/ladder/*.rb; do
    sym="ladder_$(basename "$rb" .rb)"
    "$MRUBY_SRC/build/host/bin/mrbc" -B "$sym" -o "$OBJ_DIR/$sym.c" "$rb"
    cat "$OBJ_DIR/$sym.c" >> "$OBJ_DIR/ladder_ireps.c"
  done
fi

if [[ "$GPCT" != "0" ]]; then
  # The gp-captable glue, with the resumable yield turned on. Same object name so
  # everything downstream (OBJS, the two links, the size accounting) is untouched.
  "$CLANG" -target capstone64-unknown-elf -Xclang -target-feature -Xclang +m \
    -ffreestanding -DCAPSTONE_GLUE_YIELD=1 \
    -c "$LADDER/start-gp-captable-interp.S" -o "$OBJ_DIR/start-musl.o"
  "$CLANG" -target capstone64-unknown-elf -Xclang -target-feature -Xclang +m \
    -ffreestanding -c "$LADDER/../gct-section-end.S" -o "$OBJ_DIR/gct.o"
  OBJS+=("$OBJ_DIR/start-musl.o" "$OBJ_DIR/gct.o")
else
"$CLANG" -target capstone64-unknown-elf -Xclang -target-feature -Xclang +m \
  -ffreestanding -O0 -c "$RUNTIME_DIR/start-musl.S" -o "$OBJ_DIR/start-musl.o"
OBJS+=("$OBJ_DIR/start-musl.o")
fi

"$CLANG" -target capstone64-unknown-elf -Xclang -target-feature -Xclang +m \
  -ffreestanding -O0 -c "$SETJMP_SRC" -o "$OBJ_DIR/setjmp.o"
OBJS+=("$OBJ_DIR/setjmp.o")

# MRUBY_PROBE_REVOKE=1 swaps the libc allocator for the REVOKING one: every
# allocation is an independently revocable SPLIT off a host-granted linear
# arena, and free() revokes it. That is the configuration a security number may
# be measured on; libc-ext/malloc.c is not, and says so itself.
#
# revoke_arena_domain.c defines malloc/free/realloc, and our objects precede the
# archive on the link line, so libc-ext/malloc.c is simply never pulled. The
# host program needs the same macro: it has to create and transfer a third
# region, and share order is capture order.
ARENA_FLAGS=()
HOST_FLAGS=()
if [[ ${MRUBY_PROBE_REVOKE:-0} == 1 ]]; then
  ARENA_FLAGS=(-DCAPSTONE_DOMAIN_ARENA)
  HOST_FLAGS=(-DCAPSTONE_DOMAIN_ARENA)
fi

# MRUBY_PROBE_ARENA_MB makes the arena size a VARIABLE rather than a constant to
# be edited by hand. It is the thing most likely to be the reason a workload
# stops early, because the revoking allocator never coalesces: the arena has to
# hold the whole CUMULATIVE carve, not the live set. Only meaningful with
# MRUBY_PROBE_REVOKE=1; the host and the domain must agree, and they do because
# both read this one variable.
if [[ -n ${MRUBY_PROBE_ARENA_MB:-} ]]; then
  HOST_FLAGS+=(-DHC_HOST_ARENA_SIZE="(${MRUBY_PROBE_ARENA_MB}UL * 1024 * 1024)")
fi

"$CLANG" "${MRUBY_FLAGS[@]}" "${ARENA_FLAGS[@]}" -c "$RUNTIME_DIR/hostcall.c" \
         -o "$OBJ_DIR/hostcall.o"
OBJS+=("$OBJ_DIR/hostcall.o")

if [[ ${MRUBY_PROBE_REVOKE:-0} == 1 ]]; then
  "$CLANG" "${MRUBY_FLAGS[@]}" "${ARENA_FLAGS[@]}" \
    -I"$REPO_ROOT/capstone/benchmarks/sqlite" \
    -c "$REPO_ROOT/xlang/common/revoke_arena_domain.c" -o "$OBJ_DIR/revoke_arena.o"
  OBJS+=("$OBJ_DIR/revoke_arena.o")
fi

# -U__GNUC__ for hash.c ONLY: ib_capa_to_bit calls __builtin_ctz, which crashes
# the backend (ISSUES.md C-24). Undefining __GNUC__ selects mruby's own de
# Bruijn fallback, written for compilers without the builtin. Per file, because
# y.tab.c needs __GNUC__ for alloca -- not that this build compiles y.tab.c.
# src/fmt_fp.c NARROWED to double where the tree still uses long double.
#
# `long double` is binary128 on this target and so is a capability, so it does
# not merely fail to link (C-20) -- it CRASHES the compiler, with an APInt
# assertion and therefore no source location:
#
#   clang: llvm/include/llvm/ADT/APInt.h:1565: getSExtValue():
#          Assertion `getSignificantBits() <= 64' failed.
#
# Seven of the nine pinned corpus trees are affected and all seven only in this
# one file; upstream mruby dropped long double from it by 2022.
#
# NARROWING IS SOUND HERE, and specifically: the only caller is `fmt_core`, which
# passes `mrb_float` -- a double. The value is widened to long double for the
# call and immediately narrowed back inside, so removing the parameter's width
# removes a round trip rather than precision. The algorithm itself is musl's,
# expanding the mantissa into uint32 limbs and doing base-1e9 long division, and
# LDBL_MANT_DIG only sizes that limb array.
#
# Reusing libc-ext/gen-vfprintf-double.py rather than a second transform: it is
# the same substitution on the same algorithm, and it FAILS LOUDLY if any
# 128-bit reference survives.
FMT_FP_SRC="$MRUBY_SRC/src/fmt_fp.c"
FMT_FP_GEN=""
if [[ -f $FMT_FP_SRC ]] && grep -q "long double" "$FMT_FP_SRC"; then
  FMT_FP_GEN="$OBJ_DIR/gen/fmt_fp.c"
  python3 "$SCRIPT_DIR/../libc-ext/gen-vfprintf-double.py" \
          "$MUSL_SRC_DIR" "$FMT_FP_GEN" --source "$FMT_FP_SRC"
fi

for src in "$MRUBY_SRC"/src/*.c "$MRUBY_SRC/build/host/mrblib/mrblib.c"; do
  base=$(basename "$src" .c)
  extra=()
  [[ $base == hash ]] && extra=(-U__GNUC__)
  # vm.c: DIRECT THREADING OFF on trees that have no macro for it.
  #
  # `MRB_NO_DIRECT_THREADING` only exists from mruby 3.x. Older trees turn
  # computed-goto dispatch on unconditionally the moment a GNU-ish compiler
  # builds them:
  #     #if defined __GNUC__ || defined __clang__ || defined __INTEL_COMPILER
  #     #define DIRECT_THREADED
  #     #endif
  # so our -DMRB_NO_DIRECT_THREADING is silently a no-op there and the VM ships
  # a table of absolute label addresses -- ISSUES.md C-4a, the same mechanism
  # -fno-jump-tables exists for, which does not reach `&&label` tables. The
  # domain then jumps to a LINK-TIME address and dies with cause = 1 and
  # pc == badaddr, before printing anything. Rows 9 and 14 both did.
  #
  # Undefining the compiler identity is the only lever the source offers, and it
  # is the one this build already uses for hash.c. Applied ONLY where the macro
  # is absent, so 3.x trees keep their supported switch.
  if [[ $base == vm ]] && ! grep -q "MRB_NO_DIRECT_THREADING" "$MRUBY_SRC/src/vm.c"; then
    extra=(-U__GNUC__ -U__clang__ -U__INTEL_COMPILER)
  fi
  [[ $base == fmt_fp && -n $FMT_FP_GEN ]] && src=$FMT_FP_GEN
  [[ $base == string && -n $STRING_C_GEN ]] && src=$STRING_C_GEN
  "$CLANG" "${MRUBY_FLAGS[@]}" "${extra[@]}" -c "$src" -o "$OBJ_DIR/mrb_$base.o"
  OBJS+=("$OBJ_DIR/mrb_$base.o")
done

# MRUBY_WITH_PARSER=1 adds the compiler gem, so the domain evaluates Ruby SOURCE
# instead of only precompiled bytecode. Off by default, and the order matters:
# the bytecode variant is the smaller image and it separates "does the VM run"
# from "does the parser run". Answering both in one image would leave a failure
# ambiguous between them.
PROBE_EXTRA=()
[[ ${MRUBY_PROBE_REVOKE:-0} == 1 ]] && PROBE_EXTRA+=(-DMRUBY_PROBE_REVOKE)
# MRUBY_PROBE_CDP=1 runs the corpus's largest mechanism class on the real
# interpreter; MRUBY_PROBE_CDP_CONTROL=1 is its matched arm with revocation off.
[[ ${MRUBY_PROBE_CDP:-0} == 1 ]] && PROBE_EXTRA+=(-DMRUBY_PROBE_CDP)
[[ ${MRUBY_PROBE_CDP_CONTROL:-0} == 1 ]] && PROBE_EXTRA+=(-DMRUBY_PROBE_CDP_CONTROL)
# MRUBY_PROBE_ROW=<n> runs xlang corpus row <n>'s OWN trigger.rb, embedded
# verbatim. Only rows whose pinned mruby version matches MRUBY_SRC are
# meaningful; row 10's pinned commit is the tree this port was validated on.
# MRUBY_PROBE_GEMS="eval hash-ext" links those mrbgems and generates the
# mrb_init_mrbgems the probe otherwise stubs out. Corpus triggers need them:
# row 9's first line is `eval(...)`, which is not core mruby at all, and without
# the gem the trigger raises NoMethodError before reaching its offending access
# -- a run where both arms report identically and neither means anything.
#
# Gems with an mrblib half get rake's generated loader (see below); a gem whose
# tree has not been raked is refused loudly rather than half-linked.
if [[ -n ${MRUBY_PROBE_GEMS:-} ]]; then
  GEM_INIT="$OBJ_DIR/gem_init.c"
  GEM_SYMS=()
  {
    echo '/* GENERATED by build-mruby-probe.sh -- do not edit. */'
    echo '#include <mruby.h>'
  } > "$GEM_INIT"
  for gem in $MRUBY_PROBE_GEMS; do
    # A gem can live outside the mruby tree. The corpus pins its own vulnerable
    # copy of mruby-io next to the row (build_config.rb: `conf.gem
    # File.expand_path('../mruby-io', __FILE__)`), which is the whole point --
    # the row is about THAT version. MRUBY_PROBE_GEM_PATHS is a colon-separated
    # list of extra directories to look in, searched after the mruby tree.
    GEM_DIR="$MRUBY_SRC/mrbgems/mruby-$gem"
    if [[ ! -d "$GEM_DIR/src" ]]; then
      found=""
      IFS=':' read -ra _gp <<< "${MRUBY_PROBE_GEM_PATHS:-}"
      for cand in "${_gp[@]}"; do
        [[ -n $cand && -d "$cand/mruby-$gem/src" ]] && { found="$cand/mruby-$gem"; break; }
      done
      [[ -n $found ]] || { echo "no such gem: mruby-$gem (looked in $MRUBY_SRC/mrbgems and ${MRUBY_PROBE_GEM_PATHS:-nothing})" >&2; exit 2; }
      GEM_DIR="$found"
      echo "gem mruby-$gem from $GEM_DIR"
    fi
    sym="mrb_mruby_${gem//-/_}_gem_init"
    # A gem with a RUBY half needs that half compiled to bytecode and loaded
    # before its C init runs. rake already did exactly that: build/host/mrbgems/
    # mruby-<gem>/gem_init.c holds the mrblib irep as a byte array plus a
    # GENERATED_TMP_..._gem_init that loads it and then calls the C init. Using
    # rake's file rather than regenerating it keeps one mrbc invocation and one
    # loader in the world instead of two that can disagree.
    if ls "$GEM_DIR"/mrblib/*.rb > /dev/null 2>&1; then
      gen_init="$MRUBY_SRC/build/host/mrbgems/mruby-$gem/gem_init.c"
      [[ -f $gen_init ]] || {
        echo "mruby-$gem has an mrblib half but rake has not generated" >&2
        echo "$gen_init -- run 'rake' in $MRUBY_SRC first" >&2; exit 2; }
      "$CLANG" "${MRUBY_FLAGS[@]}" -c "$gen_init" \
               -o "$OBJ_DIR/gem_${gem//-/_}_init_gen.o"
      OBJS+=("$OBJ_DIR/gem_${gem//-/_}_init_gen.o")
      sym="GENERATED_TMP_mrb_mruby_${gem//-/_}_gem_init"
    fi
    for gsrc in "$GEM_DIR"/src/*.c; do
      gbase=$(basename "$gsrc" .c)
      # A gem's own include/ comes first: mruby-io ships mruby/ext/io.h there,
      # and nothing in the mruby tree provides it.
      # -include sys/select.h, sys/time.h: mruby-io uses fd_set, FD_ZERO and
      # struct timeval without including either, which compiles against glibc
      # because <unistd.h> leaks them there and does not against musl, where they
      # live only in their own headers. A portability gap in the gem, not a
      # capability one -- and cheaper to shim here than to patch the corpus's
      # pinned copy, which has to stay byte-identical.
      "$CLANG" "${MRUBY_FLAGS[@]}" -I"$GEM_DIR/include" \
               -include sys/select.h -include sys/time.h \
               -I"$MRUBY_SRC/mrbgems/mruby-compiler/core" \
               -c "$gsrc" -o "$OBJ_DIR/gem_${gem//-/_}_$gbase.o"
      OBJS+=("$OBJ_DIR/gem_${gem//-/_}_$gbase.o")
    done
    echo "void $sym(mrb_state *mrb);" >> "$GEM_INIT"
    GEM_SYMS+=("$sym")
  done
  {
    echo 'void mrb_init_mrbgems(mrb_state *mrb) {'
    for s in "${GEM_SYMS[@]}"; do
      echo "  $s(mrb);"
    done
    echo '}'
    echo 'void mrb_final_mrbgems(mrb_state *mrb) { (void)mrb; }'
  } >> "$GEM_INIT"
  "$CLANG" "${MRUBY_FLAGS[@]}" -c "$GEM_INIT" -o "$OBJ_DIR/gem_init.o"
  OBJS+=("$OBJ_DIR/gem_init.o")
  PROBE_EXTRA+=(-DMRUBY_PROBE_GEMS)
fi

if [[ -n ${MRUBY_PROBE_ROW:-} ]]; then
  ROW_RB="$REPO_ROOT/xlang/repro/${MRUBY_PROBE_ROW}/trigger.rb"
  python3 "$SCRIPT_DIR/embed-ruby.py" "$ROW_RB" "$OBJ_DIR/row_trigger.c" row_trigger
  PROBE_EXTRA+=(-DMRUBY_PROBE_ROW="${MRUBY_PROBE_ROW}")
fi
# MRUBY_PROBE_BUMP=1 swaps the probe's allocator for an O(1) bump arena. See the
# comment in mruby_probe.c: it is the matched arm for a wedge, differing from the
# libc allocator in exactly one property.
[[ ${MRUBY_PROBE_BUMP:-0} == 1 ]] && PROBE_EXTRA+=(-DMRUBY_PROBE_BUMP)
# MRUBY_PROBE_STAGE=N builds one arm of the staged batch: 1 allocates the state,
# 2 adds mrb_gc_init, 3 adds mrb_init_core, 0 (default) is the full run. Each arm
# RETURNS a marker instead of running to the failure, so a wedge costs only the
# arms after it. See run-mruby-stages.sh.
[[ ${MRUBY_PROBE_STAGE:-0} != 0 ]] && PROBE_EXTRA+=(-DMRUBY_PROBE_STAGE="${MRUBY_PROBE_STAGE}")
if [[ ${MRUBY_WITH_PARSER:-0} == 1 ]]; then
  # y.tab.c is GENERATED from parse.y, and where rake leaves it moved: newer
  # trees keep it beside the source, older ones only under build/host. Both are
  # checked, source first, and a tree with neither fails loudly rather than
  # silently building without a parser.
  PARSER_SRC="$MRUBY_SRC/mrbgems/mruby-compiler/core"
  PARSER_GEN="$MRUBY_SRC/build/host/mrbgems/mruby-compiler/core"
  if [[ -f "$PARSER_SRC/y.tab.c" ]]; then
    PARSER_CORE="$PARSER_SRC"
  elif [[ -f "$PARSER_GEN/y.tab.c" ]]; then
    PARSER_CORE="$PARSER_GEN"
  else
    echo "no y.tab.c in $PARSER_SRC or $PARSER_GEN; run rake in $MRUBY_SRC" >&2
    exit 2
  fi
  python3 "$SCRIPT_DIR/patch-parser.py" "$PARSER_CORE/y.tab.c" \
          "$OBJ_DIR/y.tab.fixed.c"
  # codegen.c always lives with the SOURCE, even when y.tab.c does not, and both
  # include headers from the source directory.
  "$CLANG" "${MRUBY_FLAGS[@]}" -I"$PARSER_CORE" -I"$PARSER_SRC" \
           -c "$OBJ_DIR/y.tab.fixed.c" -o "$OBJ_DIR/mrb_parser.o"
  "$CLANG" "${MRUBY_FLAGS[@]}" -I"$PARSER_CORE" -I"$PARSER_SRC" \
           -c "$PARSER_SRC/codegen.c" -o "$OBJ_DIR/mrb_codegen.o"
  OBJS+=("$OBJ_DIR/mrb_parser.o" "$OBJ_DIR/mrb_codegen.o")
  PROBE_EXTRA+=(-DMRUBY_PROBE_PARSER)   # += : the bump flag must survive
fi

# MRUBY_PROBE_MRBTEST=1 runs MRUBY'S OWN TEST SUITE inside the domain.
#
# Not a new harness: `rake` in the mruby tree has already compiled test/assert.rb
# and all 43 files of test/t/*.rb to bytecode, and generated the C that loads
# them. This links those artefacts instead of reimplementing them, for the same
# reason the gem support above uses rake's gem_init.c -- one mrbc invocation and
# one loader in the world rather than two that can disagree.
#
# CORE ONLY, deliberately. mrbtest's full dispatcher (build/host/mrbgems/
# mruby-test/mrbtest.c) calls a _gem_test for each of 39 gems, and linking all of
# them would mean linking all 32 gems too -- including mruby-socket and
# mruby-io, whose tests need syscalls a domain does not have. The core suite is
# the part that exercises the interpreter itself, which is what a capability port
# has to get right first, so the dispatcher below is generated with just that
# one entry. Adding gems is a matter of extending the list, not of new machinery.
#
# HOW THE SUITE RUNS, which shapes what a failure means: gem_test.c opens a
# SEPARATE mrb_state per test file with mrb_open_core, loads assert.rb into it,
# runs that one file, hands the counts back through mrb_t_pass_result and closes
# it. So 43 interpreters are opened and torn down in sequence, and a fault in the
# 20th says the first 19 survived a full open/close cycle.
if [[ ${MRUBY_PROBE_MRBTEST:-0} == 1 ]]; then
  MRBTEST_GEM="$MRUBY_SRC/mrbgems/mruby-test"
  MRBTEST_GEN="$MRUBY_SRC/build/host/mrbgems/mruby-test"
  for f in "$MRBTEST_GEN/assert.c" "$MRBTEST_GEN/gem_test.c" \
           "$MRBTEST_GEM/driver.c" "$MRBTEST_GEM/vformat.c"; do
    [[ -f $f ]] || {
      echo "missing $f -- run 'rake test' in $MRUBY_SRC first" >&2; exit 2; }
  done
  # THE HEAP HAS TO BE BIG ENOUGH, checked HERE because the alternative is
  # finding out from a boot.
  #
  # The suite's sub-interpreters are opened with mrb_open_core(mrb_default_allocf,
  # ...) -- plain libc malloc, not the probe's instrumented arena, so the arena
  # knob does not reach them. The measured high-water for the CORE suite is
  # 828,128 bytes (MRUBY LIBCHEAP at-report). Below that, the first
  # mrb_open_core returns NULL and gem_test.c prints "Invalid mrb_state,
  # exiting", which reads like mruby failing rather than like a heap that was
  # never large enough.
  #
  # 1 MiB, i.e. the measurement plus room, and the number is now a BUILD
  # parameter rather than a property of the archive: the heap comes out of
  # dom_data, so raise it with MRUBY_DOMAIN_HEAP instead of rebuilding a libc.
  # UNDER gp-captable THIS VARIABLE NO LONGER REACHES THE ALLOCATOR, so the check
  # moves to after the link -- see the heap gate next to the dom_data sizing below.
  # malloc's storage there is the archive's `heap_fallback` array, fixed when the libc
  # was built, and the archive is BITCODE under LTO, which carries no symbol sizes at
  # all (llvm-nm prints 0 for every one of them). The only place the real size exists
  # is the linked image.
  if [[ "$GPCT" == "0" ]] && (( MRUBY_DOMAIN_HEAP < 1024 * 1024 )); then
    echo "MRUBY_DOMAIN_HEAP is $MRUBY_DOMAIN_HEAP; mrbtest needs at least 1 MiB." >&2
    echo "The core suite's measured high-water alone is 828128 bytes, and its" >&2
    echo "sub-interpreters allocate through libc malloc, not the probe arena." >&2
    exit 2
  fi
  if [[ "$GPCT" == "0" ]]; then
    echo "mrbtest: heap $MRUBY_DOMAIN_HEAP, stack $MRUBY_DOMAIN_STACK"
  else
    echo "mrbtest: stack $MRUBY_DOMAIN_STACK; heap is fixed in the archive and is"
    echo "         reported by the domain itself as MRUBY LIBCHEAP"
  fi
  # driver.c carries the command-line entry point beside the two functions this
  # actually wants (mrb_init_test_driver, mrb_t_pass_result). Renaming main
  # rather than deleting it keeps the file byte-identical to the tree's; the
  # linker drops it, since nothing calls it.
  "$CLANG" "${MRUBY_FLAGS[@]}" -Dmain=mrbtest_cli_main_unused \
           -c "$MRBTEST_GEM/driver.c" -o "$OBJ_DIR/mrbtest_driver.o"
  "$CLANG" "${MRUBY_FLAGS[@]}" -c "$MRBTEST_GEM/vformat.c" \
           -o "$OBJ_DIR/mrbtest_vformat.o"
  "$CLANG" "${MRUBY_FLAGS[@]}" -c "$MRBTEST_GEN/assert.c" \
           -o "$OBJ_DIR/mrbtest_assert.o"
  OBJS+=("$OBJ_DIR/mrbtest_driver.o" "$OBJ_DIR/mrbtest_vformat.o"
         "$OBJ_DIR/mrbtest_assert.o")

  if [[ ${MRUBY_PROBE_MRBTEST_GEMS:-0} == 1 ]]; then
    # EVERY gem and every gem's tests, using rake's own generated files
    # throughout: build/host/mrbgems/gem_init.c is the dispatcher that calls each
    # gem's GENERATED_TMP_..._gem_init in dependency order, and
    # mruby-test/mrbtest.c is the one that calls each _gem_test. Writing either
    # by hand would be a second ordering that can disagree with rake's.
    for gd in "$MRUBY_SRC"/build/host/mrbgems/mruby-*/; do
      g=$(basename "$gd")
      for gsrc in "$MRUBY_SRC/mrbgems/$g"/src/*.c; do
        [[ -e $gsrc ]] || continue
        "$CLANG" "${MRUBY_FLAGS[@]}" -I"$MRUBY_SRC/mrbgems/$g/include" \
                 -I"$MRUBY_SRC/mrbgems/mruby-compiler/core" \
                 -include sys/select.h -include sys/time.h \
                 -c "$gsrc" -o "$OBJ_DIR/wg_${g}_$(basename "$gsrc" .c).o"
        OBJS+=("$OBJ_DIR/wg_${g}_$(basename "$gsrc" .c).o")
      done
      # A gem's own C-LEVEL test helpers, which are separate from the bytecode in
      # gem_test.c: mruby-io, mruby-proc-ext and mruby-socket each define an
      # mrb_mruby_<gem>_gem_test that the generated loader calls. Omitting them
      # is three undefined symbols at link time, not a quiet loss.
      for gtest in "$MRUBY_SRC/mrbgems/$g"/test/*.c; do
        [[ -e $gtest ]] || continue
        "$CLANG" "${MRUBY_FLAGS[@]}" -I"$MRUBY_SRC/mrbgems/$g/include" \
                 -I"$MRUBY_SRC/mrbgems/mruby-compiler/core" \
                 -include sys/select.h -include sys/time.h \
                 -c "$gtest" -o "$OBJ_DIR/wt_${g}_$(basename "$gtest" .c).o"
        OBJS+=("$OBJ_DIR/wt_${g}_$(basename "$gtest" .c).o")
      done
      for gen in gem_init.c gem_test.c; do
        [[ -f "$gd/$gen" ]] || continue
        "$CLANG" "${MRUBY_FLAGS[@]}" -c "$gd/$gen" \
                 -o "$OBJ_DIR/wg_${g}_${gen%.c}.o"
        OBJS+=("$OBJ_DIR/wg_${g}_${gen%.c}.o")
      done
    done
    "$CLANG" "${MRUBY_FLAGS[@]}" -c "$MRUBY_SRC/build/host/mrbgems/gem_init.c" \
             -o "$OBJ_DIR/wg_gem_init_all.o"
    "$CLANG" "${MRUBY_FLAGS[@]}" -c "$MRBTEST_GEN/mrbtest.c" \
             -o "$OBJ_DIR/mrbtest_dispatch.o"
    OBJS+=("$OBJ_DIR/wg_gem_init_all.o" "$OBJ_DIR/mrbtest_dispatch.o")
    # Drops mruby_probe.c's empty mrb_init_mrbgems, so rake's real one links.
    PROBE_EXTRA+=(-DMRUBY_PROBE_GEMS)
  else
    "$CLANG" "${MRUBY_FLAGS[@]}" -c "$MRBTEST_GEN/gem_test.c" \
             -o "$OBJ_DIR/mrbtest_coretests.o"
    {
      echo '/* GENERATED by build-mruby-probe.sh -- do not edit. */'
      echo '#include <mruby.h>'
      echo 'void GENERATED_TMP_mrb_mruby_test_gem_test(mrb_state *mrb);'
      echo 'void mrbgemtest_init(mrb_state *mrb) {'
      echo '  GENERATED_TMP_mrb_mruby_test_gem_test(mrb);'
      echo '}'
    } > "$OBJ_DIR/mrbtest_dispatch.c"
    "$CLANG" "${MRUBY_FLAGS[@]}" -c "$OBJ_DIR/mrbtest_dispatch.c" \
             -o "$OBJ_DIR/mrbtest_dispatch.o"
    OBJS+=("$OBJ_DIR/mrbtest_coretests.o" "$OBJ_DIR/mrbtest_dispatch.o")
  fi
  PROBE_EXTRA+=(-DMRUBY_PROBE_MRBTEST)
  # NO single-file knob, on purpose. The suite already reports incrementally --
  # t_print emits one character per assertion and fflushes -- so a run that dies
  # in the 20th file still says the first 19 completed, which is the bisection a
  # staged arm would have been built to get. Adding a selector would mean
  # reimplementing rake's per-file open_core/pass_result loop, i.e. a second
  # loader that can disagree with the first.
fi

"$CLANG" "${MRUBY_FLAGS[@]}" "${PROBE_EXTRA[@]}" -I"$OBJ_DIR" \
         -c "$SCRIPT_DIR/mruby_probe.c" -o "$OBJ_DIR/mruby_probe.o"
OBJS+=("$OBJ_DIR/mruby_probe.o")

if [[ "$GPCT" != "0" ]]; then
  # link-gpfree.ld places the globals at a FIXED image offset so the monitor can
  # SPLIT the code image into a code cap and a globals cap with the real SPLIT
  # instruction. The offset has to clear .text, which is not known until something
  # is linked, so link once at a provisional 8 MiB purely to measure .text and then
  # generate the script the two real links below use. Both of them use the same
  # generated script: the second adds only the non-alloc domreq section, and the
  # existing guard right after it fails the build if any loaded byte moves.
  sed "s/0x10000 + 0x1000/0x10000 + 0x800000/" "$GPFREE/link-gpfree.ld" \
    > "$OBJ_DIR/link-probe.ld"
  "$LD_LLD" --gc-sections -T "$OBJ_DIR/link-probe.ld" -o "$OBJ_DIR/pass1.dom" \
    "${OBJS[@]}" "${LTO_LINK_FLAGS[@]}" "$ARCHIVE"
  _text=$("$CAPSTONE_LLVM_BIN/llvm-readelf" -SW "$OBJ_DIR/pass1.dom" 2>/dev/null | python3 -c '
import sys,re
for l in sys.stdin:
    m=re.match(r"\s*\[\s*\d+\]\s+(\.text)\s+\S+\s+[0-9a-f]+\s+[0-9a-f]+\s+([0-9a-f]+)", l)
    if m: print(int(m.group(2),16)); break
else: print(0)')
  [[ "${_text:-0}" -gt 0 ]] || { echo "could not measure .text for the globals offset" >&2; exit 2; }
  _goff=$(( ((_text + 0xFFFF) / 0x10000) * 0x10000 ))
  [[ $_goff -lt 65536 ]] && _goff=65536
  printf 'gp-captable: .text = %d bytes -> globals offset 0x%x\n' "$_text" "$_goff"
  LINKER_SCRIPT="$OBJ_DIR/link.ld"
  sed "s/0x10000 + 0x1000/0x10000 + $(printf '0x%x' $_goff)/" "$GPFREE/link-gpfree.ld" \
    > "$LINKER_SCRIPT"
fi

# THE STACK RESERVE IS LINKED INTO **BOTH** LINKS, and that is what keeps the
# no-loaded-byte-moved check below meaningful.
#
# It used to appear only in the second link. Under the default ABI that was
# invisible: it overrides a weak definition already in the archive, so the object
# set changed but the layout did not. Under gp-captable it is a GLOBAL, and a new
# global appends a record to .capstone_gp_initdesc -- which is the first thing in
# the globals region, so every global behind it shifts. The check then failed
# naming domreq.S, which had not done anything.
#
# Adding it here makes the two links differ by exactly ONE thing, the non-alloc
# domreq section, which is the thing the check is actually about. The three size
# variables move up with it because it is emitted from them; the definitions are
# self-defaulting, so an explicit MRUBY_DOMAIN_STACK from the environment still
# wins and nothing downstream changes.
printf 'unsigned long __capstone_stack_reserve = %luUL;\n' "$MRUBY_DOMAIN_STACK" \
  > "$OBJ_DIR/stack_reserve.c"
"$CLANG" "${MRUBY_FLAGS[@]}" -c "$OBJ_DIR/stack_reserve.c" \
         -o "$OBJ_DIR/stack_reserve.o"

"$LD_LLD" --gc-sections -T "$LINKER_SCRIPT" -o "$OUT_DOM" \
          "${OBJS[@]}" "$OBJ_DIR/stack_reserve.o" "${LTO_LINK_FLAGS[@]}" "$ARCHIVE"

# DECLARE THE DOMAIN'S RESOURCE REQUIREMENT, because the module's fallback rule
# no longer fits an image this size.
#
# Without a .capstone_domreq section the module sizes ONE region as
#     code_len + DOMAIN_DATA_SIZE + max(2 * code_len, 512 KiB)
# and asks the buddy allocator for it. At code_len 1,393,968 that is 4,247,440
# bytes, which rounds to order 11 -- one past MAX_ORDER-1 -- so __get_free_pages
# returns NULL and the run dies as `create_dom failed (-1)`, with the reason in a
# pr_alert the driver has already muted. The 3x-on-the-image rule is a proxy for
# stack depth and this domain is exactly where the proxy breaks: the image is
# large because mruby is large, not because it recurses three megabytes deep.
#
# Declaring turns that into two regions the stock allocator hands out without
# complaint: code align16(code_len) -> order 9, data 1536 + the number below.
# dom_data for this domain is PURE STACK -- it is not gp-captable, so there is no
# cap-table carve, and .bss lives inside the loaded segment (link.ld puts it last
# as NOBITS, inside p_memsz). start-musl.S takes the dom_data capability from
# cscratch and sets sp to its END, so the whole region is the stack.
#
# 1 MiB MINUS THE SEAL, and the subtraction is the point. The module sizes the
# data region as MONITOR_SEAL_SIZE + what the image declares, then rounds that up
# to a power of two -- so declaring a round 1 MiB asks for 1048576 + 1536, which
# rounds to 2 MiB and wastes half of it. Declaring 1 MiB - 1536 lands the region
# exactly on 1 MiB. A round number is the wrong number here.
#
# The size itself is what the domain effectively had before: a 2 MiB single
# region minus a 1.39 MB image left it about 701 KB, and it ran. Raise it with
# MRUBY_DOMAIN_STACK if a deeper workload needs it -- mruby's own test suite
# will -- and keep the "- 1536" when you do.
# TWO NUMBERS NOW, because dom_data holds two things.
#
# libc-ext/malloc.c takes its heap from the LOW end of dom_data and the stack
# grows down from the high end, so the declaration is heap + stack and the split
# has to be told to both sides: to the module through .capstone_domreq, and to
# the libc through __capstone_stack_reserve. Emitting the reserve from the same
# variable is the point -- a build that declared one number and linked another
# would put the two ends of the region on a collision course silently.
# UNDER gp-captable THE DECLARATION CANNOT BE heap + stack, because there is no
# separate heap: malloc's storage is a GLOBAL like any other, carved out of dom_data
# by the entry glue along with the other 2660. What dom_data has to hold is the
# monitor's blob copy, the cap table, every global's storage, and then the stack. The
# heap+stack formula under-declared it by ~350 KB and domdata-budget.py said so --
# "storage 1191728 ... = STACK -349856 ... DOES NOT FIT" -- which is the whole reason
# that script exists.
#
# The numbers come from the script rather than from a second implementation here: it
# already parses the descriptor the glue will walk, and two calculations of the same
# thing drift. A parse that finds nothing is a hard error, never a zero.
if [[ "$GPCT" != "0" ]]; then
  _budget=$(PATH="$CAPSTONE_LLVM_BIN:$PATH" python3 \
    "$REPO_ROOT/capstone/tests/runtime-qemu/silicon-ladder/domdata-budget.py" "$OUT_DOM" 2>&1)
  _carve=$(printf '%s\n' "$_budget" | python3 -c '
import re,sys
t=sys.stdin.read()
got={}
for k,pat in (("blob",r"- blob\s+(\d+)"),("table",r"- cap table\s+(\d+)"),("storage",r"- storage\s+(\d+)")):
    m=re.search(pat,t)
    if not m: sys.exit("domdata-budget.py printed no %s line; refusing to guess" % k)
    got[k]=int(m.group(1))
print(got["blob"]+got["table"]+got["storage"])')
  [[ "${_carve:-0}" -gt 0 ]] || { echo "could not read the carve size from domdata-budget.py" >&2
                                  printf '%s\n' "$_budget" >&2; exit 2; }
  MRUBY_DOMAIN_DATA=$(( _carve + MRUBY_DOMAIN_STACK ))
  printf 'gp-captable: carve %d + stack %d -> dom_data %d\n' \
         "$_carve" "$MRUBY_DOMAIN_STACK" "$MRUBY_DOMAIN_DATA"

  # NO PRE-FLIGHT HEAP GATE HERE, deliberately. Under gp-captable malloc's storage is
  # the archive's `heap_fallback`, fixed when the libc was built -- and it is reachable
  # from neither side: the LTO archive is bitcode, which carries no symbol sizes, and
  # in the image the symbol is static and LTO has internalized it away. Both were
  # tried; both report 0 or nothing, which is precisely the shape of check this project
  # keeps getting burned by.
  #
  # The domain reports the real number itself, every run:
  #     MRUBY LIBCHEAP at-exit: used=157232 of=1048576
  # so the measurement exists where it is trustworthy. mrbtest's high-water is 828128
  # bytes; a libc built with less will show it there. Raise it by rebuilding the
  # archive with MUSL_CAPSTONE_EXTRA_CFLAGS=... -DCAPSTONE_LIBC_HEAP_BYTES=...
fi

# (the three size variables and stack_reserve.o are produced above, before the
# first link -- see the note there on why they cannot live only down here)
_segs() { "$CAPSTONE_LLVM_READOBJ" --program-headers "$OUT_DOM" \
          | grep -E 'Offset|FileSize|MemSize|VirtualAddress'; }
_before=$(_segs)
"$CLANG" -target capstone64-unknown-elf -ffreestanding \
  -DCAPSTONE_DOMREQ_DATA=$MRUBY_DOMAIN_DATA \
  -DCAPSTONE_DOMREQ_STACK=$MRUBY_DOMAIN_STACK \
  -c "$REPO_ROOT/capstone/tests/runtime-qemu/domreq.S" -o "$OBJ_DIR/domreq.o"
# The libc's weak default is overridden by stack_reserve.o, emitted above from the
# SAME variable this declaration uses, so the module's idea of the split and the
# allocator's cannot drift apart.
"$LD_LLD" --gc-sections -T "$LINKER_SCRIPT" -o "$OUT_DOM" \
          "${OBJS[@]}" "$OBJ_DIR/domreq.o" "$OBJ_DIR/stack_reserve.o" \
          "${LTO_LINK_FLAGS[@]}" "$ARCHIVE"
# The section is non-alloc, so NOTHING LOADED MAY MOVE. Verified rather than
# asserted: this project has a documented layout sensitivity where four added
# instructions flipped a passing run, and a diagnostic that perturbs the image is
# how that was found.
if [[ "$(_segs)" != "$_before" ]]; then
  echo "domreq.S moved a loaded byte; the declaration must be non-alloc" >&2
  exit 2
fi

image=$("$CAPSTONE_LLVM_READOBJ" --program-headers "$OUT_DOM" \
         | awk '/MemSize/ {print $2; exit}')
# Report the TWO regions the module will actually allocate, not the single one it
# used to. The old line printed `tot - image - 1536`, i.e. what was left over
# inside one power-of-two block after the image -- a number that stopped being
# true the moment this domain started declaring its requirement, and that read
# like a measurement rather than the leftover it was.
_code=$(( ((image - 1) / 16 + 1) * 16 ))
_creg=4096; while (( _creg < _code )); do _creg=$(( _creg * 2 )); done
_dreg=4096; while (( _dreg < 1536 + MRUBY_DOMAIN_DATA )); do _dreg=$(( _dreg * 2 )); done
printf 'built %s (image %s -> code region %s; dom_data %s = heap %s + stack %s -> data region %s)\n' \
       "$OUT_DOM" "$image" "$_creg" "$MRUBY_DOMAIN_DATA" "$MRUBY_DOMAIN_HEAP" \
       "$MRUBY_DOMAIN_STACK" "$_dreg"
# Both regions come from __get_free_pages, so both are bounded by MAX_ORDER-1 =
# order 10. Say so HERE rather than letting the guest report `create_dom failed
# (-1)` with the reason in a muted pr_alert -- which is exactly how the previous
# failure presented, and it cost a boot to read.
for _r in "code:$_creg" "data:$_dreg"; do
  if (( ${_r#*:} > 4 * 1024 * 1024 )); then
    echo "${_r%%:*} region wants ${_r#*:} bytes, past the buddy allocator's" >&2
    echo "order-10 maximum of 4194304; the module cannot allocate it" >&2
    exit 2
  fi
done

"$GUEST_CC" -O2 "${HOST_FLAGS[@]}" -o "$OUT_HOST" "$RUNTIME_DIR/hostcall_host.c" "$LIBCAPSTONE_C"
printf 'built %s\n' "$OUT_HOST"
